    help_step2_goal: "লক্ষ্য: আপনার শারীরিক হার্ডওয়্যার কোথায় রাখবেন তা স্বয়ংক্রিয়ভাবে গণনা করুন।",
    help_step2_1: "GeoJSON ফাইল আপলোড করার পরে, সিস্টেম K-Means ক্লাস্টারিং চালাবে।",
    help_step2_2: "এটি স্বয়ংক্রিয়ভাবে আপনার মাস্টার হাব এবং সাবহাবের জন্য সবচেয়ে অনুকূল বাস্তব-জগতের স্থানাঙ্কগুলি বের করে।",
    help_step2_3: "গণনা করা খরচ ব্রেকডাউন এবং আপনার জন্য তৈরি করা সঠিক মানচিত্রের অবস্থান পর্যালোচনা করুন।",
    help_step3_goal: "লক্ষ্য: নিরাপদে শিক্ষামূলক ভিডিও আপলোড করুন এবং পাঠ্যক্রমের বিরুদ্ধে সেগুলি যাচাই করুন৷",
    help_step3_1: "পাঠ্যক্রম ট্যাবে নেভিগেট করুন এবং একটি ভিডিও ফাইল আপলোড করুন।",
    help_step3_2: "সিস্টেমটি স্বয়ংক্রিয়ভাবে ভিডিও অডিওকে একটি পাঠ্য প্রতিলিপিতে রূপান্তর করবে (AI ব্যবহার করে)।",
    help_step3_3: "স্থানীয় পাঠ্যক্রমের সাথে সামঞ্জস্যপূর্ণ কিনা তা যাচাই করতে এটি নিরাপদে এই পাঠ্যটিকে Amazon Bedrock (Claude 3 AI) এ পাঠায়।",
    help_step3_4: "অনুমোদিত হলে, ভিডিওটি স্থায়ীভাবে আপনার ক্লাউড ডাটাবেসে স্বয়ংক্রিয়ভাবে সংরক্ষিত হয়!",
    help_step4_tuner_goal: "লক্ষ্য: এআই সিস্টেমে স্থানীয় জ্ঞান (পাঠ্যপুস্তক, পরীক্ষা) খাওয়ান।",
