    help_step4_tuner_2: "এআই আদর্শ উত্তর নিদর্শন শেখানোর জন্য পরীক্ষার কাগজপত্র এবং ম্যাচিং মার্কিং স্কিম আপলোড করুন।",
    help_step4_tuner_3: "Google Colab-এ নিরাপদ, উচ্চ-গতির প্রশিক্ষণের জন্য Google Drive-এ ডেটা ম্যানিফেস্ট রপ্তানি করুন।",
    help_step5_goal: "লক্ষ্য: সম্পূর্ণ অফলাইনে শিক্ষার্থীদের কাছে যাচাইকৃত ভিডিও পাঠান।",
    help_step5_1: "মাস্টার হাব ক্লাউড থেকে নতুন অনুমোদিত ভিডিও ডাউনলোড করবে।",
    help_step5_2: "এটি তারপর সমস্ত অফলাইন P2P সাবহাবগুলিতে সামগ্রী বিতরণ করতে দীর্ঘ-পরিসরের রেডিও সংকেত ব্যবহার করে।",
