    master_hub_backbone: "సౌరశక్తితో నడిచే మెష్ బ్యాక్‌బోన్ & AI కోర్ సర్వర్",
    sub_hub_receiver: "రిసీవర్ నోడ్ & లోకల్ స్టూడెంట్ యాక్సెస్ పాయింట్",
    annual_maintenance: "వార్షిక నిర్వహణ (OPEX)",
    year: "సంవత్సరం",
    help_guide_intro: "స్వాగతం! పైప్‌లైన్‌ను సులభంగా కాన్ఫిగర్ చేయడంలో మరియు ప్రో లాగా అప్లికేషన్‌ను అమలు చేయడంలో ఎవరికైనా సహాయపడేలా ఈ గైడ్ రూపొందించబడింది. ప్రాంతాలను విశ్లేషించడానికి, కంటెంట్‌ను ధృవీకరించడానికి మరియు మీ మెష్ నెట్‌వర్క్‌ని అమలు చేయడానికి ఈ సాధారణ దశలను అనుసరించండి.",
    help_step1_goal: "లక్ష్యం: మీరు నెట్‌వర్క్‌ని నిర్మించాలనుకుంటున్న భౌతిక ప్రాంత సరిహద్దులను నిర్వచించండి.",
    help_step1_1: "మ్యాప్‌లో మీ లక్ష్య ప్రాంతం చుట్టూ సరిహద్దు పెట్టెను సులభంగా గీయడానికి geojson.ioకి వెళ్లండి.",
    help_step1_2: "ఫైల్‌ను మీ కంప్యూటర్‌కు డౌన్‌లోడ్ చేయడానికి సేవ్ > GeoJSON క్లిక్ చేయండి.",
    help_step1_3: "ఈ యాప్‌లోని హబ్ ప్లేస్‌మెంట్ ట్యాబ్‌కు నావిగేట్ చేసి, ఫైల్‌ను అప్‌లోడ్ చేయండి.",
    help_step2_goal: "లక్ష్యం: మీ భౌతిక హార్డ్‌వేర్‌ను ఎక్కడ ఉంచాలో స్వయంచాలకంగా లెక్కించండి.",
    help_step2_1: "GeoJSON ఫైల్‌ను అప్‌లోడ్ చేసిన తర్వాత, సిస్టమ్ K-మీన్స్ క్లస్టరింగ్‌ని అమలు చేస్తుంది.",
    help_step2_2: "ఇది మీ మాస్టర్ హబ్ మరియు సబ్‌హబ్‌ల కోసం అత్యంత అనుకూలమైన వాస్తవ-ప్రపంచ కోఆర్డినేట్‌లను స్వయంచాలకంగా గుర్తిస్తుంది.",
    help_step2_3: "లెక్కించిన ధరల విభజన మరియు మీ కోసం రూపొందించబడిన ఖచ్చితమైన మ్యాప్ స్థానాలను సమీక్షించండి.",
    help_step3_goal: "లక్ష్యం: విద్యా సంబంధిత వీడియోలను సురక్షితంగా అప్‌లోడ్ చేయండి మరియు వాటిని పాఠ్యాంశాలకు అనుగుణంగా ధృవీకరించండి.",
    help_step3_1: "కరికులమ్ ట్యాబ్‌కు నావిగేట్ చేయండి మరియు వీడియో ఫైల్‌ను అప్‌లోడ్ చేయండి.",
    help_step3_2: "సిస్టమ్ స్వయంచాలకంగా వీడియో ఆడియోను టెక్స్ట్ ట్రాన్స్‌క్రిప్ట్‌గా మారుస్తుంది (AIని ఉపయోగించి).",
    help_step3_3: "ఇది స్థానిక సిలబస్‌తో సమలేఖనం చేయబడిందో లేదో ధృవీకరించడానికి ఈ వచనాన్ని అమెజాన్ బెడ్‌రాక్ (క్లాడ్ 3 AI)కి సురక్షితంగా పంపుతుంది.",
    help_step3_4: "ఆమోదించబడితే, వీడియో స్వయంచాలకంగా మీ క్లౌడ్ డేటాబేస్‌లో శాశ్వతంగా సేవ్ చేయబడుతుంది!",
    help_step4_tuner_goal: "లక్ష్యం: AI వ్యవస్థకు స్థానిక పరిజ్ఞానాన్ని (పాఠ్యపుస్తకాలు, పరీక్షలు) అందించండి.",
    help_step4_tuner_1: "స్థానిక AI ట్యూటర్ ట్యాబ్‌కు నావిగేట్ చేయండి మరియు KPM-ఆమోదిత పాఠ్యపుస్తకాలను అప్‌లోడ్ చేయండి.",
    help_step4_tuner_2: "AI ఆదర్శ సమాధానాల నమూనాలను బోధించడానికి పరీక్షా పత్రాలు మరియు మ్యాచింగ్ మార్కింగ్ స్కీమ్‌లను అప్‌లోడ్ చేయండి.",
    help_step4_tuner_3: "Google Colabలో సురక్షితమైన, అధిక-వేగవంతమైన శిక్షణ కోసం డేటా మానిఫెస్ట్‌ను Google డిస్క్‌కి ఎగుమతి చేయండి.",
    help_step5_goal: "లక్ష్యం: ధృవీకరించబడిన వీడియోలను పూర్తిగా ఆఫ్‌లైన్‌లో విద్యార్థులకు పంపండి.",
    help_step5_1: "మాస్టర్ హబ్ క్లౌడ్ నుండి కొత్తగా ఆమోదించబడిన వీడియోలను డౌన్‌లోడ్ చేస్తుంది.",
    help_step5_2: "ఇది అన్ని ఆఫ్‌లైన్ P2P సబ్‌హబ్‌లకు కంటెంట్‌ను పంపిణీ చేయడానికి దీర్ఘ-శ్రేణి రేడియో సిగ్నల్‌లను ఉపయోగిస్తుంది.",
    help_step5_3: "విద్యార్థులు ఇప్పుడు ఇంటర్నెట్ అవసరం లేకుండా వారి స్థానిక హబ్ నుండి నేరుగా తాజా విద్యా కంటెంట్‌ను యాక్సెస్ చేయవచ్చు!",
    help_aws_config: "సిస్టమ్ అడ్మినిస్ట్రేటర్ కాన్ఫిగరేషన్ (AWS)",
