    exam_papers_desc: "ఎడమవైపున ప్రశ్న పత్రాలను అప్‌లోడ్ చేయండి, కుడివైపున సరిపోలే మార్కింగ్ స్కీమ్‌లు లేదా నమూనా సమాధానాలు. ప్రతి జత ప్రశ్న → కీలకపదాలు → ఆదర్శ సమాధానాన్ని మ్యాప్ చేయడానికి AIకి నేర్పుతుంది. పరీక్షల డేటా ఎల్లప్పుడూ పాఠ్యపుస్తకాల కంటే ప్రాధాన్యతనిస్తుంది.",
    exam_warning: "ప్రతి ప్రశ్నాపత్రాన్ని దాని ఖచ్చితమైన మార్కింగ్ పథకంతో సరిపోల్చండి. సరిపోలని జత AIకి తప్పు సమాధానాలను నేర్పుతుంది. మీకు ఇంకా స్కీమ్ లేకపోతే, ఆ పేపర్‌ని దాటవేసి, తర్వాత తిరిగి రండి.",
