    help_step2_1: "GeoJSON ਫਾਈਲ ਨੂੰ ਅਪਲੋਡ ਕਰਨ ਤੋਂ ਬਾਅਦ, ਸਿਸਟਮ K-Means ਕਲੱਸਟਰਿੰਗ ਨੂੰ ਲਾਗੂ ਕਰੇਗਾ।",
