    help_step3_goal: "ਟੀਚਾ: ਵਿਦਿਅਕ ਵੀਡੀਓਜ਼ ਨੂੰ ਸੁਰੱਖਿਅਤ ਢੰਗ ਨਾਲ ਅੱਪਲੋਡ ਕਰੋ ਅਤੇ ਪਾਠਕ੍ਰਮ ਦੇ ਵਿਰੁੱਧ ਉਹਨਾਂ ਦੀ ਪੁਸ਼ਟੀ ਕਰੋ।",
