    help_step3_3: "ਇਹ ਤਸਦੀਕ ਕਰਨ ਲਈ ਕਿ ਕੀ ਇਹ ਸਥਾਨਕ ਸਿਲੇਬਸ ਨਾਲ ਮੇਲ ਖਾਂਦਾ ਹੈ, ਇਸ ਟੈਕਸਟ ਨੂੰ ਸੁਰੱਖਿਅਤ ਰੂਪ ਨਾਲ ਐਮਾਜ਼ਾਨ ਬੈਡਰੋਕ (ਕਲਾਡ 3 ਏਆਈ) ਨੂੰ ਭੇਜਦਾ ਹੈ।",
