    help_step4_tuner_goal: "ਟੀਚਾ: AI ਸਿਸਟਮ ਨੂੰ ਸਥਾਨਕ ਗਿਆਨ (ਪਾਠ ਪੁਸਤਕਾਂ, ਪ੍ਰੀਖਿਆਵਾਂ) ਫੀਡ ਕਰੋ।",
    help_step4_tuner_1: "ਸਥਾਨਕ AI ਟਿਊਟਰ ਟੈਬ 'ਤੇ ਨੈਵੀਗੇਟ ਕਰੋ ਅਤੇ KPM-ਪ੍ਰਵਾਨਿਤ ਪਾਠ-ਪੁਸਤਕਾਂ ਨੂੰ ਅੱਪਲੋਡ ਕਰੋ।",
