    help_step4_tuner_3: "Google Colab 'ਤੇ ਸੁਰੱਖਿਅਤ, ਉੱਚ-ਸਪੀਡ ਸਿਖਲਾਈ ਲਈ ਡੇਟਾ ਮੈਨੀਫੈਸਟ ਨੂੰ Google Drive ਵਿੱਚ ਨਿਰਯਾਤ ਕਰੋ।",
