    help_guide_intro: "வருக! இந்த வழிகாட்டி, பைப்லைனை எளிதாக உள்ளமைக்கவும், ஒரு சார்பு போல பயன்பாட்டை இயக்கவும் எவருக்கும் உதவும் வகையில் வடிவமைக்கப்பட்டுள்ளது. பகுதிகளை பகுப்பாய்வு செய்யவும், உள்ளடக்கத்தை சரிபார்க்கவும் மற்றும் உங்கள் மெஷ் நெட்வொர்க்கை பயன்படுத்தவும் இந்த எளிய வழிமுறைகளைப் பின்பற்றவும்.",
    help_step1_goal: "இலக்கு: நீங்கள் பிணையத்தை உருவாக்க விரும்பும் இயற்பியல் பகுதி எல்லைகளை வரையறுக்கவும்.",
    help_step1_1: "வரைபடத்தில் உங்கள் இலக்குப் பகுதியைச் சுற்றி எல்லைப் பெட்டியை எளிதாக வரைய geojson.io க்குச் செல்லவும்.",
    help_step1_2: "உங்கள் கணினியில் கோப்பைப் பதிவிறக்க, சேமி > GeoJSON என்பதைக் கிளிக் செய்யவும்.",
    help_step1_3: "இந்தப் பயன்பாட்டில் உள்ள ஹப் பிளேஸ்மென்ட் தாவலுக்குச் சென்று கோப்பைப் பதிவேற்றவும்.",
    help_step2_goal: "இலக்கு: உங்கள் இயற்பியல் வன்பொருளை எங்கு வைக்க வேண்டும் என்பதை தானாக கணக்கிடுங்கள்.",
    help_step2_1: "GeoJSON கோப்பைப் பதிவேற்றிய பிறகு, கணினி K-Means கிளஸ்டரிங்கை இயக்கும்.",
    help_step2_2: "இது உங்கள் மாஸ்டர் ஹப் மற்றும் சப்ஹப்களுக்கான மிகவும் உகந்த நிஜ உலக ஆயங்களை தானாகவே கண்டுபிடிக்கும்.",
    help_step2_3: "கணக்கிடப்பட்ட செலவு விவரம் மற்றும் உங்களுக்காக உருவாக்கப்பட்ட சரியான வரைபட இருப்பிடங்களை மதிப்பாய்வு செய்யவும்.",
    help_step3_goal: "இலக்கு: கல்வி தொடர்பான வீடியோக்களை பாதுகாப்பாக பதிவேற்றி, பாடத்திட்டத்திற்கு எதிராக அவற்றைச் சரிபார்க்கவும்.",
    help_step3_1: "பாடத்திட்ட தாவலுக்குச் சென்று வீடியோ கோப்பைப் பதிவேற்றவும்.",
    help_step3_2: "கணினி தானாகவே வீடியோ ஆடியோவை உரை டிரான்ஸ்கிரிப்டாக மாற்றும் (AI ஐப் பயன்படுத்தி).",
    help_step3_3: "இது உள்ளூர் பாடத்திட்டத்துடன் ஒத்துப்போகிறதா என்பதைச் சரிபார்க்க, இந்த உரையை Amazon Bedrockக்கு (Claude 3 AI) பாதுகாப்பாக அனுப்புகிறது.",
    help_step3_4: "அங்கீகரிக்கப்பட்டால், வீடியோ தானாகவே உங்கள் கிளவுட் தரவுத்தளத்தில் நிரந்தரமாகச் சேமிக்கப்படும்!",
    help_step4_tuner_goal: "இலக்கு: AI அமைப்புக்கு உள்ளூர் அறிவை (பாடப்புத்தகங்கள், தேர்வுகள்) ஊட்டவும்.",
    help_step4_tuner_1: "உள்ளூர் AI ஆசிரியர் தாவலுக்குச் சென்று KPM-அங்கீகரிக்கப்பட்ட பாடப்புத்தகங்களைப் பதிவேற்றவும்.",
    help_step4_tuner_2: "AI ஐடியல் பதில் முறைகளை கற்பிக்க, தேர்வுத் தாள்கள் மற்றும் பொருத்தமான மதிப்பெண் திட்டங்களைப் பதிவேற்றவும்.",
    help_step4_tuner_3: "Google Colab இல் பாதுகாப்பான, அதிவேகப் பயிற்சிக்காக, தரவு மேனிஃபெஸ்டை Google Drive க்கு ஏற்றுமதி செய்யவும்.",
    help_step5_goal: "இலக்கு: சரிபார்க்கப்பட்ட வீடியோக்களை முற்றிலும் ஆஃப்லைனில் மாணவர்களுக்கு அனுப்பவும்.",
    help_step5_1: "மாஸ்டர் ஹப் புதிதாக அங்கீகரிக்கப்பட்ட வீடியோக்களை மேகக்கணியில் இருந்து பதிவிறக்கும்.",
    help_step5_2: "அனைத்து ஆஃப்லைன் P2P சப்ஹப்களுக்கும் உள்ளடக்கத்தை விநியோகிக்க நீண்ட தூர ரேடியோ சிக்னல்களைப் பயன்படுத்துகிறது.",
    help_step5_3: "மாணவர்கள் இப்போது இணையம் தேவையில்லாமல், அவர்களின் உள்ளூர் மையத்திலிருந்து நேரடியாக சமீபத்திய கல்வி உள்ளடக்கத்தை அணுகலாம்!",
    help_aws_config: "கணினி நிர்வாகி கட்டமைப்பு (AWS)",
    help_aws_desc: "உள்ளடக்க உட்செலுத்துதல் பைப்லைன் (படி 3) செயல்படுவதை உறுதிசெய்ய, ஒரு நிர்வாகி AWS நற்சான்றிதழ்களை பின்தள சேவையகத்தில் உள்ளமைக்க வேண்டும்.",
    help_contact_builder: "அல்லது கூடுதல் உதவிக்கு இந்தத் திட்டத்தை உருவாக்கியவரைத் தொடர்புகொள்ளவும்:",
