    exam_papers_title: "தேர்வுத் தாள்கள் + மதிப்பெண் திட்டங்கள்",
    exam_papers_desc: "இடதுபுறத்தில் வினாத் தாள்களைப் பதிவேற்றவும், பொருத்தமான குறிக்கும் திட்டங்கள் அல்லது மாதிரி பதில்களை வலதுபுறத்தில் பதிவேற்றவும். ஒவ்வொரு ஜோடியும் AIக்கு கேள்வி → முக்கிய வார்த்தைகள் → சிறந்த பதிலை வரைபடமாக்க கற்றுக்கொடுக்கிறது. தேர்வுத் தரவுகள் எப்போதும் பாடப்புத்தகங்களை விட முன்னுரிமை பெறுகின்றன.",
    exam_warning: "ஒவ்வொரு வினாத்தாளையும் அதன் சரியான மதிப்பெண் திட்டத்துடன் பொருத்தவும். பொருந்தாத ஜோடி AIக்கு தவறான பதில்களைக் கற்பிக்கும். உங்களிடம் இன்னும் திட்டம் இல்லையென்றால், அந்தக் காகிதத்தைத் தவிர்த்துவிட்டு, பிறகு வரவும்.",
