    multifile: "பல கோப்பு",
    manifest_compiled_tip: "மேனிஃபெஸ்ட் தொகுக்கப்பட்டது. பயிற்சியின் போது பாடப்புத்தக உள்ளடக்கத்தை விட தேர்வு ஜோடிகள் தானாகவே 3× எடை பெருக்கியைப் பெறும். எந்த பாடப்புத்தக உள்ளடக்கமும் குறியிடும் திட்டத்துடன் முரண்பட்டால், குறிக்கும் திட்டம் வெற்றி பெறும்.",
